"use strict";
const routes={"index":{"label":"All editions","url":"/editions/"},"english":{"label":"English · source text","url":"/editions/english"},"morse":{"label":"International Morse","url":"/editions/morse"},"braille":{"label":"English Braille · Unicode","url":"/editions/braille"},"brf":{"label":"English Braille · embossable BRF","url":"/editions/braille.brf"},"nato":{"label":"NATO phonetic alphabet","url":"/editions/nato"},"languages":{"label":"Other languages · coverage","url":"/editions/languages"},"sign":{"label":"Sign languages · not available yet","url":"/editions/sign"},"voice":{"label":"Scout voice agent · not available yet","url":"/editions/voice"}};
const aliases={english:'english',en:'english',original:'english',source:'english',morse:'morse','international morse':'morse','morse code':'morse',braille:'braille','unicode braille':'braille','english braille':'braille',brf:'brf','braille ready':'brf','braille-ready':'brf',emboss:'brf',nato:'nato','nato phonetic':'nato','nato phonetic alphabet':'nato','phonetic alphabet':'nato',french:'french',fr:'french',francais:'french',spanish:'spanish',es:'spanish',espanol:'spanish',languages:'languages',translations:'languages',sign:'sign','sign language':'sign',asl:'sign',bsl:'sign',voice:'voice',scout:'voice',index:'index','all editions':'index'};
const status=document.getElementById('selection-status');
function openEdition(id,typed){const entry=routes[id];if(entry&&entry.url){window.location.assign(entry.url);return;}status.textContent=entry?entry.label+'. This edition has not been made. This language has not been translated yet.':(typed?'“'+typed+'” is not available yet.':'Type a language or encoding first.')+' No translation has been generated.';}
document.getElementById('select-form').addEventListener('submit',event=>{event.preventDefault();openEdition(document.getElementById('edition-select').value,'');});
document.getElementById('type-form').addEventListener('submit',event=>{event.preventDefault();const typed=document.getElementById('edition-name').value.trim();const key=typed.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,' ');openEdition(aliases[key],typed);});
